package DigitalAssets::Policy;

use strict;
use warnings;

use Moo;
use MooX::StrictConstructor;
use MooX::TypeTiny;
use Types::Standard qw(ArrayRef HashRef Str);

has actions => (
    is      => 'ro',
    isa     => HashRef,
    default => sub {
        return { map { $_ => 1 } qw(
            docx-to-pdf docx-to-markdown docx-to-text docx-to-html
            docx-read-metadata docx-edit-metadata docx-remove-metadata
            pdf-to-png pdf-to-jpeg pdf-to-docx pdf-to-text markdown-to-pdf
            pdf-extract-images pdf-merge pdf-burst pdf-extract-pages
            pdf-remove-pages pdf-rotate-pages pdf-edit-content
            pdf-edit-bookmarks pdf-edit-qdf pdf-repair pdf-inspect pdf-encrypt
            pdf-decrypt pdf-linearize pdf-add-page-numbers pdf-add-watermark
            pdf-extract-bookmarks pdf-read-metadata pdf-edit-metadata
            pdf-remove-metadata image-to-png image-to-jpeg image-to-webp
            image-resize image-crop image-rotate image-flop image-flip
            image-grayscale image-optimize-png image-optimize-jpeg
            image-create-gif image-read-metadata image-edit-metadata
            image-remove-metadata
        ) };
    },
);

sub assert_action {
    my ($self, $action) = @_;
    defined($action) && $action =~ /\A[a-z0-9-]+\z/ && $self->actions()->{$action}
        or die "labwc-digital-assets-action: unsupported Digital Assets action\n";
    return $action;
}

