    #include if exists <abstractions/nameservice-strict>

    /usr/bin/perl mr,
    /opt/acme-perl/ r,
    /opt/acme-perl/** r,

    /var/lib/acme-perl/ r,
    /var/lib/acme-perl/** rwk,

    # Restrict additional module search trees to reviewed locations.
    /usr/share/perl5/** r,
    /usr/lib/@{multiarch}/perl*/** mr,

    /usr/bin/sendmail Px -> organization.acme-mail-submit,

