A shell workload should explicitly enumerate both the interpreter and external commands:

```apparmor
#include <tunables/global>

profile organization.acme-shell-job {
    #include <abstractions/base>
    #include if exists <abstractions/nameservice-strict>

    # Select only the interpreter actually required.
    /bin/dash rix,
    # /bin/bash rix,
    # /usr/bin/zsh rix,

    /opt/acme-maintenance/ r,
    /opt/acme-maintenance/** r,

    /var/lib/acme-maintenance/ r,
    /var/lib/acme-maintenance/** rwk,
    /run/acme-maintenance/ r,
    /run/acme-maintenance/** rwk,

    # Explicit command vocabulary.
    /usr/bin/{awk,basename,cat,cut,date,dirname,find,grep,head,id,printf} ix,
    /usr/bin/{readlink,sed,sort,stat,tail,tr,uname,uniq,wc} ix,
    /bin/{cat,cp,echo,ln,mkdir,mv,rm,rmdir,sleep} ix,

    # Example controlled systemd interaction.
    /usr/bin/systemctl ix,
    /run/systemd/private rw,
    /run/dbus/system_bus_socket rw,

    audit deny /usr/bin/{curl,wget,nc,ncat,socat,ssh,scp} x,
    audit deny /usr/bin/{sudo,su,pkexec} x,
    audit deny owner @{HOME}/** wklx,

    #include if exists <local/organization.acme-shell-job>
}
```

Do not combine dash, Bash, and zsh rules by default. Bash startup files, zsh plugin frameworks, shell functions, `BASH_ENV`, `ENV`, `ZDOTDIR`, command substitution, and arbitrary helper execution materially alter the attack surface. A maintenance script that needs `curl`, `ssh`, package management, and unrestricted `systemctl` is effectively an administrative program and should be treated as such rather than “just a shell script.”

AppArmor requires read permission for interpreted script content, and its standard abstractions include interpreter-specific policy such as Perl and Bash support. Named-profile execution avoids imposing one policy on every program that happens to use the same interpreter. citeturn18search0turn10search32

### Shell wrappers and binary wrappers

A minimal shell launcher is acceptable where bypass prevention does not rely on the launcher being an ELF attachment:

```sh
#!/bin/dash
set -eu

exec /usr/bin/aa-exec \
    -p organization.acme-python-job -- \
    /usr/bin/python3 -I /opt/acme/bin/job.py "$@"
```

Install it root-owned and non-writable by the target user:

```bash
sudo install -o root -g root -m 0755 \
    acme-python-job /usr/local/bin/acme-python-job
```

For stronger entrypoint control, use a root-owned ELF wrapper with an attached launcher profile. The wrapper can set close-on-exec on inherited descriptors, sanitize the environment, request a profile transition on the next `execve`, and then start the interpreter.

```c
#define _GNU_SOURCE
#include <errno.h>
#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <sys/apparmor.h>
#include <unistd.h>

static void mark_extra_fds_close_on_exec(void) {
    long max_fd = sysconf(_SC_OPEN_MAX);
    if (max_fd < 0 || max_fd > 65536) {
        max_fd = 65536;
    }

    for (int fd = STDERR_FILENO + 1; fd < max_fd; ++fd) {
        int flags = fcntl(fd, F_GETFD);
        if (flags >= 0) {
            (void)fcntl(fd, F_SETFD, flags | FD_CLOEXEC);
        }
    }
}

int main(int argc, char **argv) {
    const char *profile = "organization.acme-python-job";
    const char *python = "/usr/bin/python3";
    const char *script = "/opt/acme/bin/job.py";

    if (argc > 128) {
        fprintf(stderr, "Too many arguments\n");
        return 64;
    }

    clearenv();
    if (setenv("PATH", "/usr/bin:/bin", 1) != 0 ||
        setenv("LANG", "C.UTF-8", 1) != 0) {
        perror("setenv");
        return 70;
    }

    mark_extra_fds_close_on_exec();

    if (aa_change_onexec(profile) != 0) {
        perror("aa_change_onexec");
        return 77;
    }

    char **child_argv = calloc((size_t)argc + 3, sizeof(char *));
    if (child_argv == NULL) {
        perror("calloc");
        return 70;
    }

    child_argv[0] = (char *)python;
    child_argv[1] = "-I";
    child_argv[2] = (char *)script;

    for (int i = 1; i < argc; ++i) {
        child_argv[i + 2] = argv[i];
    }
    child_argv[argc + 2] = NULL;

    execv(python, child_argv);
    perror("execv");
    return errno == ENOENT ? 127 : 126;
}
```

Compile and install:

```bash
cc -O2 -D_FORTIFY_SOURCE=3 -fstack-protector-strong \
   -Wall -Wextra -Werror \
