sudo install -o root -g root -m 0755 \
    acme-python-launcher \
    /usr/libexec/acme-python-launcher
```

The launcher profile:

```apparmor
#include <tunables/global>

profile organization.acme-python-launcher /usr/libexec/acme-python-launcher {
    #include <abstractions/base>

    # Permission to execute the next image; aa_change_onexec selects the
    # target profile for that exec.
    /usr/bin/python3 ix,

    change_profile -> organization.acme-python-job,

    audit deny owner @{HOME}/** rwklx,
    audit deny /usr/bin/{sudo,su,pkexec} x,

    #include if exists <local/organization.acme-python-launcher>
