--- d-i/forky/hooks/shared/target/etc/apparmor.d/abstractions/managed-bwrap-desktop-runtime ---
# Managed by unattended-installer.
#
# Runtime policy for applications that stay inside labwc-managed-app's
# Bubblewrap payload domain. Bubblewrap sets no_new_privs before exec, so those
# payloads cannot gain permission by transitioning into their top-level
# attachment. Keep the common Electron and desktop-runtime access in this
# capability-free abstraction; namespace-construction privileges remain in
# managed-bwrap-common and application installation trees remain explicit in
# the caller.

#include <abstractions/managed-electron-runtime>

# Managed applications use their existing per-application profiles when
# launched directly. Their Bubblewrap payloads need the same client-side
# network primitives, but remain restricted by the separate Bubblewrap
# network namespace when the launcher selects private networking.
network inet stream,
network inet6 stream,
network inet dgram,
network inet6 dgram,

--- d-i/forky/hooks/shared/target/etc/apparmor.d/abstractions/managed-crun-runtime ---
# Managed by unattended-installer.
#
# crun is the final OCI runtime boundary for both rootless and service-owned
# Podman workloads. It must construct namespaces, mounts, cgroups, consoles,
# and process supervision state before handing execution to an OCI-selected
# AppArmor profile. Keep these runtime mechanics repository-owned so crun does
# not depend on package abstractions or a package profile's optional local
# include contract. Package abstractions can carry explicit deny rules and are
# intentionally not included in this complete OCI runtime boundary.

io_uring,
mqueue,
userns,

capability,

network,
unix,
dbus,

mount,
remount,
umount,
pivot_root,

ptrace,
signal,

# OCI runtimes may request a named workload profile after the container root
# has been assembled. Cover both an immediate aa_change_profile() request and
# an aa_change_onexec() request for an arbitrary container init path and target
# profile without relying on the package's crun profile or local/crun extension.
change_profile -> **,
change_profile unsafe /** -> **,

