/etc/alsa/** r,
/etc/asound.conf r,
/etc/openal/alsoft.conf r,
/etc/pipewire/ r,
/etc/pipewire/** r,
/etc/pulse/ r,
/etc/pulse/** r,
/usr/share/alsa/ r,
/usr/share/alsa/** r,
/usr/share/openal/ r,
/usr/share/openal/** r,
/usr/share/pipewire/ r,
/usr/share/pipewire/** r,
/usr/share/sounds/ r,
/usr/share/sounds/** r,

