        !$actions{$entry->{action}}++
            or die "Digital Assets catalog contains a duplicate action\n";
        !$labels{"$entry->{category}\0$entry->{label}"}++
            or die "Digital Assets catalog contains a duplicate category label\n";
    }

    $validated = 1;
    return;
}

sub action_entries {
    _validate_catalog();
