   169	sub from_environment {
   170	    my ($class) = @_;
   171	
   172	    require_value($> != 0, 'labwc-adb-action must run as the logged-in desktop user');
   173	
   174	    for my $override (qw(ADB_SERVER_SOCKET ANDROID_ADB_SERVER_PORT)) {
   175	        require_value(
   176	            !defined($ENV{$override}) || $ENV{$override} eq q{},
   177	            "$override overrides are not supported by the managed launcher",
   178	        );
   179	    }
   180	
   181	    my $runtime_dir = $ENV{XDG_RUNTIME_DIR};
   182	    $runtime_dir = File::Spec->catdir('/run/user', $<)
   183	        if !defined($runtime_dir) || $runtime_dir eq q{};
   184	    _validate_runtime_dir($runtime_dir);
   185	
   186	    my $home = $ENV{HOME};
   187	    _validate_home($home);
   188	
   189	    my %tool_paths;
   190	    for my $tool (qw(adb df ss timeout)) {
   191	        $tool_paths{$tool} = _resolve_tool($tool, 1);
   192	    }
   193	    for my $tool (qw(fastboot notify_send samloader samsung_extractor terminal)) {
   194	        $tool_paths{$tool} = _resolve_tool($tool, 0);
   195	    }
   196	
   197	    return $class->new(
   198	        runtime_dir   => $runtime_dir,
   199	        home          => $home,
   200	        server_marker => File::Spec->catfile($runtime_dir, 'labwc-adb-server.managed'),
   201	        tool_paths    => \%tool_paths,
   202	    );
   203	}
