   256	sub _resolve_tool {
   257	    my ($name, $required) = @_;
   258	    my $candidates = $TOOL_CANDIDATES{$name};
   259	    defined($candidates) or fail("unknown managed Android tool: $name");
   260	
   261	    for my $candidate (@{$candidates}) {
   262	        next if !-e $candidate || !-x $candidate;
   263	        my $resolved = abs_path($candidate);
   264	        next if !defined($resolved) || !-f $resolved || !-x $resolved;
   265	        return $candidate;
   266	    }
   267	
   268	    fail("required Android Debug Bridge command is not installed: $name") if $required;
