    86	sub stop {
    87	    my ($self) = @_;
    88	    if (!$self->port_in_use) {
    89	        $self->clear_marker;
    90	        print "ADB server is already stopped.\n";
    91	        return 0;
    92	    }
    93	    $self->is_managed
    94	        or fail(
    95	            'TCP port ' . $self->config->adb_server_port
    96	                . ' is not owned by this managed desktop session',
    97	        );
    98	    $self->probe
    99	        or fail(
   100	            'managed ADB server is unresponsive; refusing process-table discovery or name-wide termination',
   101	        );
   102	
   103	    $self->command->run_quiet(
   104	        10,
   105	        $self->config->require_tool('adb'),
   106	        'kill-server',
   107	    );
   108	    $self->wait_for_exit
   109	        or fail(
   110	            'ADB server did not release TCP port '
   111	                . $self->config->adb_server_port
   112	                . ' after kill-server',
   113	        );
   114	    print "ADB server stopped.\n";
   115	    return 0;
   116	}
