   118	sub start_once {
   119	    my ($self) = @_;
   120	    if ($self->port_in_use) {
   121	        $self->is_managed
   122	            or fail(
   123	                'TCP port ' . $self->config->adb_server_port
   124	                    . ' is not owned by this managed desktop session',
   125	            );
   126	        return $self->probe;
   127	    }
   128	
   129	    my $status = $self->command->run_signal(
   130	        'TERM',
   131	        3,
   132	        $self->config->adb_start_seconds,
   133	        $self->config->require_tool('adb'),
   134	        'start-server',
   135	    );
   136	    return 0 if $status != 0;
   137	
   138	    for (1 .. 10) {
   139	        if ($self->port_in_use && $self->probe) {
   140	            $self->mark_managed;
   141	            return 1;
   142	        }
   143	        sleep 1;
   144	    }
   145	    return 0;
   146	}
