   148	sub start {
   149	    my ($self) = @_;
   150	    if ($self->port_in_use && $self->is_managed && $self->probe) {
   151	        print "ADB server is already running and responsive.\n";
   152	        return $self->command->run(
   153	            $self->config->adb_probe_seconds,
   154	            $self->config->require_tool('adb'),
   155	            'server-status',
   156	        );
   157	    }
   158	
   159	    if ($self->port_in_use) {
   160	        $self->is_managed
   161	            or fail(
   162	                'TCP port ' . $self->config->adb_server_port
   163	                    . ' is not owned by this managed desktop session',
   164	            );
   165	        fail(
   166	            'managed ADB server is unresponsive; explicit session restart is required',
   167	        );
   168	    }
   169	
   170	    for my $attempt (1 .. 2) {
   171	        if ($self->start_once) {
   172	            print "ADB server started and passed its responsiveness probe.\n";
   173	            return $self->command->run(
   174	                $self->config->adb_probe_seconds,
   175	                $self->config->require_tool('adb'),
   176	                'server-status',
   177	            );
   178	        }
   179	        print STDERR "ADB server start attempt $attempt failed; retrying without process-table discovery.\n";
   180	        $self->clear_marker;
   181	    }
   182	
   183	    fail('ADB server failed to become responsive after two bounded attempts');
   184	}
