   199	        or fail(
   200	            'TCP port ' . $self->config->adb_server_port
   201	                . ' is not owned by this managed desktop session',
   202	        );
   203	    return 1 if $self->probe;
   204	    fail(
   205	        'managed ADB server is unresponsive; refusing process-table discovery or name-wide termination',
