    69	sub device_state {
    70	    my ($self, $serial) = @_;
    71	    validate_serial($serial);
    72	    my $devices = $self->capture_devices;
    73	    for my $line (split /\n/, $devices) {
    74	        next if $line !~ /\S/;
    75	        my ($line_serial, $state) = split /\s+/, $line, 3;
    76	        next if !defined($line_serial) || $line_serial ne $serial;
    77	        return 'no-permissions' if index($line, 'no permissions') >= 0;
    78	        return defined($state) && $state ne q{} ? $state : 'unknown';
    79	    }
    80	    return 'disconnected';
