    83	sub explain_state {
    84	    my ($self, $serial) = @_;
    85	    my $state = $self->device_state($serial);
    86	    if ($state eq 'device') {
    87	        print "Device $serial is connected and authorized.\n";
    88	    }
    89	    elsif ($state eq 'unauthorized') {
    90	        print "Device $serial is unauthorized.\n";
    91	        print "Unlock the phone, accept the RSA USB-debugging prompt, then retry.\n";
    92	        print "If no prompt appears, revoke USB debugging authorizations on the phone, reconnect the cable, and accept the new key.\n";
    93	    }
    94	    elsif ($state eq 'no-permissions') {
    95	        print "Device $serial is visible but the desktop session lacks USB permission.\n";
    96	        print "Confirm the user is in plugdev, log out and back in after installation, reconnect the cable, and verify the managed udev rules loaded.\n";
    97	        print "Use a data-capable USB cable and select a USB mode that exposes Android debugging.\n";
    98	    }
    99	    elsif ($state eq 'offline') {
   100	        print "Device $serial is offline.\n";
   101	        print "The launcher can reconnect offline transports; otherwise unlock and reconnect the device, then retry.\n";
   102	    }
   103	    elsif ($state eq 'disconnected') {
   104	        print "Device $serial is disconnected.\n";
   105	        print "Reconnect the USB cable or wireless endpoint. Device actions wait up to 60 seconds for the same serial to return.\n";
   106	    }
   107	    else {
   108	        print "Device $serial reports state: $state\n";
   109	    }
   110	    return $state;
   111	}
