   113	sub wait_for_serial {
   114	    my ($self, $serial) = @_;
   115	    validate_serial($serial);
   116	    $self->server->ensure_responsive;
   117	
   118	    my $state = $self->device_state($serial);
   119	    if ($state eq 'device') {
   120	        return 1;
   121	    }
   122	    if ($state eq 'unauthorized' || $state eq 'no-permissions') {
   123	        $self->explain_state($serial);
   124	        fail('device is not ready for commands');
   125	    }
   126	    if ($state eq 'offline') {
   127	        print "Device $serial is offline; requesting a transport reconnect.\n";
   128	        $self->command->run_quiet(
   129	            12,
   130	            $self->config->require_tool('adb'),
   131	            '-s',
   132	            $serial,
   133	            'reconnect',
   134	        );
   135	    }
   136	    elsif ($state eq 'disconnected') {
   137	        print 'Waiting up to '
   138	            . $self->config->adb_wait_seconds
   139	            . " seconds for device $serial to reconnect.\n";
   140	    }
   141	
   142	    my $status = $self->command->run_signal(
   143	        'TERM',
   144	        3,
   145	        $self->config->adb_wait_seconds,
   146	        $self->config->require_tool('adb'),
   147	        '-s',
   148	        $serial,
   149	        'wait-for-device',
   150	    );
   151	    if ($status != 0) {
   152	        $self->explain_state($serial);
   153	        fail("timed out waiting for device $serial");
   154	    }
   155	
   156	    $state = $self->device_state($serial);
   157	    if ($state ne 'device') {
   158	        $self->explain_state($serial);
   159	        fail('device returned but is not authorized and ready');
   160	    }
   161	    return 1;
   162	}
