   189	sub _preflight_space {
   190	    my ($self, $serial, $backup_root) = @_;
   191	    my $device_df;
   192	    eval {
   193	        $device_df = $self->device->capture_serial(
   194	            30,
   195	            $serial,
   196	            'shell',
   197	            'df',
   198	            '-k',
   199	            '/sdcard',
   200	        );
   201	        1;
   202	    };
   203	
   204	    my $device_used;
   205	    if (defined($device_df)) {
   206	        for my $line (split /\n/, $device_df) {
   207	            my @fields = split /\s+/, $line;
   208	            $device_used = $fields[2]
   209	                if @fields >= 3 && defined($fields[2]) && $fields[2] =~ /\A[0-9]+\z/;
   210	        }
   211	    }
   212	    my $available = eval { $self->storage->available_kib($backup_root) };
   213	    if (
   214	        !defined($device_used)
   215	            || !defined($available)
   216	            || $device_used !~ /\A[0-9]+\z/
   217	            || $available !~ /\A[0-9]+\z/
   218	    ) {
   219	        print STDERR "Warning: unable to compare device usage with host free space; the backup may fail if storage is exhausted.\n";
   220	        return;
   221	    }
   222	    my $required = $device_used + $self->config->adb_backup_headroom_kib;
   223	    require_value(
   224	        $available >= $required,
   225	        "backup requires at least $required KiB free, but only $available KiB is available",
   226	    );
   227	    print "Backup storage preflight: device-shared-used=$device_used KiB host-available=$available KiB.\n";
   228	    return;
   229	}
