   399	sub _wait_for_single_download_device {
   400	    my ($self) = @_;
   401	    print 'Waiting up to '
   402	        . $self->config->samsung_download_wait_seconds
   403	        . " seconds for Samsung Download Mode.\n";
   404	    my $status = $self->command->run_signal(
   405	        'TERM',
   406	        5,
   407	        $self->config->samsung_download_wait_seconds,
   408	        $self->config->require_tool(
   409	            'samloader',
   410	            'samloader-rs is not installed',
   411	        ),
   412	        '--usb-backend',
   413	        'libusb',
   414	        'detect',
   415	        '--wait',
   416	    );
   417	    $status == 0
   418	        or fail('samloader did not detect a supported Samsung Download Mode device');
   419	
   420	    my $count = $self->_count_download_devices;
   421	    require_value(
   422	        $count == 1,
   423	        "exactly one supported Samsung Download Mode device is required; found $count",
   424	    );
   425	    return;
   426	}
   427	
   428	sub _count_download_devices {
   429	    my ($self) = @_;
   430	    my $root = '/sys/bus/usb/devices';
   431	    opendir my $directory, $root
   432	        or fail("unable to inspect USB devices for Samsung Download Mode: $!");
   433	    my $count = 0;
   434	    while (my $entry = readdir $directory) {
   435	        next if $entry eq q{.} || $entry eq q{..};
   436	        my $base = File::Spec->catdir($root, $entry);
   437	        my $vendor_path = File::Spec->catfile($base, 'idVendor');
   438	        my $product_path = File::Spec->catfile($base, 'idProduct');
   439	        next if !-r $vendor_path || !-r $product_path;
   440	        my $vendor = _read_trimmed($vendor_path);
   441	        next if !defined($vendor) || lc($vendor) ne '04e8';
   442	        my $product = _read_trimmed($product_path);
   443	        ++$count if defined($product) && lc($product) =~ /\A(?:6601|685d|68c3)\z/;
   444	    }
   445	    closedir $directory;
   446	    return $count;
   447	}
   448	
   449	sub _read_trimmed {
   450	    my ($path) = @_;
   451	    open my $file, '<', $path or return undef;
   452	    my $value = <$file>;
   453	    close $file;
   454	    return undef if !defined($value);
   455	    return _trim($value);
   456	}
   457	
   458	sub _trim {
   459	    my ($value) = @_;
   460	    $value //= q{};
   461	    $value =~ s/\r//g;
   462	    $value =~ s/\A\s+//;
   463	    $value =~ s/\s+\z//;
   464	    return $value;
   465	}
