    92	sub command_path {
    93	    my ($self, $name) = @_;
    94	    $name =~ /\A[A-Za-z0-9][A-Za-z0-9+_.-]*\z/
    95	        or _fatal('invalid command name');
    96	    for my $directory (qw(/usr/local/bin /usr/local/sbin /usr/bin /usr/sbin /bin /sbin)) {
    97	        my $candidate = "$directory/$name";
    98	        return $candidate if -f $candidate && !-l $candidate && -x $candidate;
    99	    }
   100	    _fatal("required command is not installed: $name");
   101	}
