   103	sub _status_detail {
   104	    my ($status) = @_;
   105	    return "exec error: $!" if $status == -1;
   106	    return 'terminated by signal ' . WTERMSIG($status) if WIFSIGNALED($status);
   107	    return 'exit status ' . WEXITSTATUS($status) if WIFEXITED($status);
   108	    return 'unknown process status';
