   111	sub _run {
   112	    my ($self, $allow_failure, @command) = @_;
   113	    @command && defined $command[0] or _fatal('empty command');
   114	    my $status = system { $command[0] } @command;
   115	    return $status if $allow_failure || $status == 0;
   116	    _fatal('command failed: ' . _status_detail($status));
   117	}
