   119	sub run_timed {
   120	    my ($self, @command) = @_;
   121	    my $timeout = $self->command_path('timeout');
   122	    return $self->_run(
   123	        0,
   124	        $timeout,
   125	        '--signal=TERM',
   126	        '--kill-after=15s',
   127	        $self->timeout_seconds() . 's',
   128	        @command,
   129	    );
