   153	sub capture_timed {
   154	    my ($self, $limit, @command) = @_;
   155	    $limit > 0 or _fatal('capture limit must be positive');
   156	    my $timeout = $self->command_path('timeout');
   157	    open my $fh, '-|', $timeout, '--signal=TERM', '--kill-after=15s',
   158	        $self->timeout_seconds() . 's', @command
   159	        or _fatal("cannot start command for output capture: $!");
   160	    binmode $fh, ':raw';
   161	    my $output = q{};
   162	    while (1) {
   163	        my $buffer = q{};
   164	        my $read = read($fh, $buffer, 65_536);
   165	        defined($read) or _fatal("cannot read command output: $!");
   166	        last if $read == 0;
   167	        length($output) + $read <= $limit
   168	            or _fatal('command output exceeds the permitted safety limit');
   169	        $output .= $buffer;
   170	    }
   171	    close $fh or _fatal('captured command failed');
   172	    return $output;
   173	}
