   175	sub create_private_file {
   176	    my ($self, $name, $content) = @_;
   177	    $name =~ /\A[A-Za-z0-9._-]+\z/ or _fatal('unsafe workspace file name');
   178	    my ($fh, $temporary) = tempfile(".$name.XXXXXX", DIR => $self->work_directory(), UNLINK => 0);
   179	    binmode $fh, ':raw';
   180	    print {$fh} $content or _fatal("cannot write workspace file: $!");
   181	    close $fh or _fatal("cannot close workspace file: $!");
   182	    chmod 0600, $temporary or _fatal("cannot secure workspace file: $!");
   183	    my $target = $self->work_directory() . "/$name";
   184	    rename $temporary, $target or _fatal("cannot publish workspace file: $!");
