   188	sub prepare_output_file {
   189	    my ($self, $operation, $extension, $source_path) = @_;
   190	    $operation =~ /\A[A-Za-z0-9-]+\z/ or _fatal('invalid output operation');
   191	    $extension =~ /\A[A-Za-z0-9]+\z/ or _fatal('invalid output extension');
   192	    my $directory = $self->_output_directory($operation);
