   274	sub notify_result {
   275	    my ($self, $summary, $body) = @_;
   276	    return if !defined($ENV{DBUS_SESSION_BUS_ADDRESS}) || !length($ENV{DBUS_SESSION_BUS_ADDRESS});
   277	    my $notify = eval { $self->command_path('notify-send') };
   278	    return if !$notify;
   279	    my $pid = fork();
   280	    return if !defined $pid;
   281	    if ($pid == 0) {
   282	        open STDOUT, '>', '/dev/null' or POSIX::_exit(0);
   283	        open STDERR, '>&', \*STDOUT or POSIX::_exit(0);
