   285	            '-i', 'document-save', '-c', 'x-labwc.maintenance', '-t', '10000',
   286	            $summary, $body;
   287	        POSIX::_exit($executed ? 0 : 127);
   288	    }
   289	    waitpid($pid, 0);
   290	}
