   336	sub validate_user_file {
   337	    my ($self, $kind, $requested_path) = @_;
   338	    _safe_absolute_path('selected path', $requested_path);
   339	    $requested_path !~ /[\r\n]/ or _fatal('selected path cannot contain newlines');
   340	    !-l $requested_path && -f $requested_path && -r $requested_path
   341	        or _fatal('selected path must be a readable non-symbolic regular file');
   342	    my $resolved = abs_path($requested_path);
