   350	    ($stat[2] & 0022) == 0
   351	        or _fatal('selected file cannot be writable by group or other users');
   352	    $stat[7] > 0 && $stat[7] <= $self->max_input_bytes()
   353	        or _fatal('selected file is empty or exceeds the safety size limit');
