   370	    my ($self, $kind, $list_path) = @_;
   371	    my $runtime = $self->runtime_directory();
   372	    $list_path =~ /\A\Q$runtime\E\/labwc-digital-assets-list\.[A-Za-z0-9]+\z/
   373	        or _fatal('selection list is outside the managed runtime directory');
   374	    -f $list_path && !-l $list_path
