--- managed-wrapper-perl abstraction ---
     1	# Managed by unattended-installer.
     2	#
     3	# System Perl runtime for repository-owned wrappers. The package abstraction
     4	# supplies package-owned module paths; explicit deny rules prevent repository
     5	# wrappers from importing modules or executing helper code from user-managed
     6	# Perl installation trees.
     7	
     8	#include <abstractions/managed-wrapper-base>
     9	#include <abstractions/perl>
