   399	        image    => qr/\.(?:avif|bmp|gif|heic|jpe?g|png|tiff?|webp)\z/i,
   400	    );
   401	    exists $patterns{$kind} && $path =~ $patterns{$kind}
   402	        or _fatal("selected file does not have a supported $kind extension");
   403	}
   404	
   405	sub read_input_list {
   406	    my ($self, $kind, $list_path) = @_;
   407	    my $runtime = $self->runtime_directory();
   408	    $list_path =~ /\A\Q$runtime\E\/labwc-digital-assets-list\.[A-Za-z0-9]+\z/
   409	        or _fatal('selection list is outside the managed runtime directory');
   410	    -f $list_path && !-l $list_path
   411	        or _fatal('selection list is not a regular file');
   412	    my @stat = lstat $list_path;
   413	    $stat[4] == $< && ($stat[2] & 07777) == 0600
   414	        or _fatal('selection list ownership or mode is unsafe');
   415	    $stat[7] <= 16_384 or _fatal('selection list exceeds the managed size limit');
   416	    open my $fh, '<:encoding(UTF-8)', $list_path
   417	        or _fatal("cannot read selection list: $!");
   418	    my @files;
   419	    while (my $line = <$fh>) {
   420	        $line =~ s/\r?\n\z//;
   421	        push @files, $self->validate_user_file($kind, $line);
   422	        @files <= $self->max_multi_files()
   423	            or _fatal('too many files in managed selection list');
   424	    }
   425	    close $fh or _fatal("cannot close selection list: $!");
   426	    @files >= 2 or _fatal('select at least two input files');
   427	    return \@files;
   428	}
   429	
   430	sub pdf_page_count {
   431	    my ($self, $path) = @_;
   432	    my $pdfinfo = $self->command_path('pdfinfo');
   433	    my $output = $self->capture_timed(65_536, $pdfinfo, $path);
   434	    my ($pages) = $output =~ /^Pages:\s*([0-9]+)\s*$/m;
   435	    defined($pages) && $pages >= 1 && $pages <= $self->max_pdf_pages()
   436	        or _fatal('unable to determine a supported PDF page count');
   437	    return int($pages);
   438	}
   439	
   440	sub validate_page_range {
   441	    my ($self, $range, $total_pages) = @_;
   442	    $range =~ /\A[0-9]+(?:-[0-9]+)?(?:,[0-9]+(?:-[0-9]+)?)*\z/
   443	        or _fatal('page range must be a comma-separated list such as 1-3,5');
   444	    for my $part (split /,/, $range) {
   445	        my ($first, $last) = split /-/, $part, 2;
   446	        $last //= $first;
   447	        $first >= 1 && $last >= $first && $last <= $total_pages
   448	            or _fatal('page range contains a page outside the source PDF');
   449	    }
   450	    return $range;
   451	}
   452	
   453	sub prompt_page_range {
   454	    my ($self, $total_pages) = @_;
   455	    return $self->validate_page_range(
   456	        $self->prompt_line("Pages (1-$total_pages, for example 1-3,5): "),
   457	        $total_pages,
   458	    );
   459	}
   460	
   461	sub directory_has_file {
   462	    my ($self, $directory, $expression) = @_;
   463	    opendir my $dh, $directory or _fatal("cannot inspect output directory: $!");
   464	    while (my $entry = readdir $dh) {
   465	        next if $entry eq '.' || $entry eq '..';
   466	        my $path = "$directory/$entry";
   467	        if (-f $path && !-l $path && $entry =~ $expression) {
   468	            closedir $dh;
   469	            return 1;
   470	        }
   471	    }
   472	    closedir $dh or _fatal("cannot close output directory: $!");
   473	    return 0;
   474	}
   475	
   476	1;
   477	package DigitalAssets::PDF;
   478	
   479	use strict;
   480	use warnings;
   481	
   482	use Cwd qw(abs_path);
   483	use Moo;
   484	use MooX::StrictConstructor;
   485	use MooX::TypeTiny;
   486	
   487	has context  => ( is => 'ro', required => 1 );
   488	has metadata => ( is => 'ro', required => 1 );
   489	
   490	sub to_png {
   491	    my ($self, $input_path) = @_;
   492	    my $context = $self->context();
   493	    $context->pdf_page_count($input_path);
   494	    my $directory = $context->prepare_output_directory('pdf-to-png');
   495	    $context->run_timed($context->command_path('pdftoppm'), '-r', '150', '-png', $input_path, "$directory/page");
   496	    $context->directory_has_file($directory, qr/\Apage-[0-9]+\.png\z/)
   497	        or die "labwc-digital-assets-action: PDF conversion did not create PNG files\n";
   498	    $context->report_directory_output($directory, 'PNG pages');
   499	}
   500	
   501	sub to_jpeg {
   502	    my ($self, $input_path) = @_;
   503	    my $context = $self->context();
   504	    $context->pdf_page_count($input_path);
   505	    my $directory = $context->prepare_output_directory('pdf-to-jpeg');
   506	    $context->run_timed(
   507	        $context->command_path('pdftoppm'),
   508	        '-r', '150', '-jpeg', '-jpegopt', 'quality=90', $input_path, "$directory/page",
   509	    );
   510	    $context->directory_has_file($directory, qr/\Apage-[0-9]+\.jpg\z/)
   511	        or die "labwc-digital-assets-action: PDF conversion did not create JPEG files\n";
   512	    $context->report_directory_output($directory, 'JPEG pages');
   513	}
   514	
   515	sub to_docx {
   516	    my ($self, $input_path) = @_;
   517	    my $context = $self->context();
   518	    $context->pdf_page_count($input_path);
   519	    my $output = $context->prepare_output_file('pdf-to-docx', 'docx', $input_path);
   520	    $self->_run_managed_python(
   521	        $self->_pdf_tool_python(),
   522	        'pdf-to-docx.py',
   523	        <<'PYTHON',
   524	from pathlib import Path
   525	from pdf2docx import Converter
   526	import sys
   527	
   528	source = Path(sys.argv[1])
   529	destination = Path(sys.argv[2])
   530	converter = Converter(str(source))
   531	try:
   532	    converter.convert(str(destination))
   533	finally:
   534	    converter.close()
   535	PYTHON
   536	        $input_path,
   537	        $output,
   538	    );
   539	    $context->report_file_output($output, 'DOCX file');
   540	}
   541	
   542	sub to_text {
   543	    my ($self, $input_path) = @_;
   544	    my $context = $self->context();
   545	    my $output = $context->prepare_output_file('pdf-to-text', 'txt', $input_path);
   546	    $context->run_timed($context->command_path('pdftotext'), '-layout', $input_path, $output);
   547	    $context->report_file_output($output, 'plain-text file');
   548	}
   549	
   550	sub markdown_to_pdf {
   551	    my ($self, $input_path) = @_;
   552	    my $context = $self->context();
   553	    my $output = $context->prepare_output_file('markdown-to-pdf', 'pdf', $input_path);
   554	    $context->command_path('typst');
   555	    $context->run_timed(
   556	        $context->command_path('pandoc'),
   557	        '--from=markdown', '--to=pdf', '--pdf-engine=/usr/local/bin/typst',
   558	        "--output=$output", $input_path,
   559	    );
   560	    $context->report_file_output($output, 'PDF');

